#requires -Version 5.1
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
$root=Join-Path $PSScriptRoot 'common\src\main\resources\assets\akaishi\textures\block'
$previewDir=Join-Path $PSScriptRoot 'gui_layouts'; New-Item -ItemType Directory -Force $previewDir | Out-Null
function Fill($g,$x,$y,$w,$h,$c){$b=New-Object Drawing.SolidBrush([Drawing.ColorTranslator]::FromHtml($c));try{$g.FillRectangle($b,$x,$y,$w,$h)}finally{$b.Dispose()}}
function Paint($name,$face,$accent){$bmp=New-Object Drawing.Bitmap(64,64);$g=[Drawing.Graphics]::FromImage($bmp);try{$g.Clear([Drawing.Color]::FromArgb(255,25,31,38));Fill $g 2 2 60 60 '#7A8791';Fill $g 5 5 54 54 '#202A33';Fill $g 8 8 48 48 '#394955';if($face -eq 'top'){Fill $g 14 14 36 36 '#111A22';Fill $g 18 18 28 28 $accent;Fill $g 23 23 18 18 '#263B43'}elseif($face -eq 'bottom'){for($x=12;$x -lt 54;$x+=8){Fill $g $x 12 3 40 '#AAB5BA';Fill $g ($x+3) 12 2 40 '#18232B'}}else{Fill $g 13 14 38 34 '#111A22';Fill $g 17 18 30 26 $accent;Fill $g 23 23 18 14 '#273B43';Fill $g 27 25 4 10 '#D5F4E5';for($x=17;$x -lt 49;$x+=8){Fill $g $x 50 4 3 $accent}}foreach($p in @(5,56)){Fill $g $p 5 3 3 '#D8E0E3';Fill $g $p 57 3 3 '#D8E0E3'}$path=Join-Path $root ($name+'_'+$face+'.png');$bmp.Save($path,[Drawing.Imaging.ImageFormat]::Png);return $bmp}finally{$g.Dispose()}}
$targets=@(@('akaishi_activated_fractionator','#5CC8D7'),@('akaishi_energy_aggregator','#E0B23B'),@('akaishi_energy_liquefier','#4BA9D1'),@('akaishi_energy_processor','#86A9C7'),@('akaishi_equipment_forger','#B776D6'),@('akaishi_super_generator_core','#F08A45'))
$all=@();foreach($t in $targets){$faces=@();foreach($f in @('top','side','bottom')){$b=Paint $t[0] $f $t[1];$faces+=$b;$all+=$b};$sheet=New-Object Drawing.Bitmap(212,76);$sg=[Drawing.Graphics]::FromImage($sheet);$sg.Clear([Drawing.Color]::FromArgb(255,12,15,19));for($i=0;$i -lt 3;$i++){$sg.DrawImageUnscaled($faces[$i],(4+$i*70),6)}$sg.Dispose();$sheet.Save((Join-Path $previewDir ($t[0]+'_batch_preview.png')),[Drawing.Imaging.ImageFormat]::Png);$sheet.Dispose();$faces|% Dispose}
Write-Output 'SUCCESS: painted 12 native 64x64 machine textures; blockstate/model JSON untouched.'